//! The look shared with LagScope Pulse: colours, radii, fonts and status shapes from
//! lagscope-core's design/tokens.json (pinned in Cargo.toml, generated by build.rs). The window
//! (win::gui) and the HTML report both take their colours from here.

/// An sRGB colour from the tokens.
#[derive(Clone, Copy, PartialEq, Debug)]
pub struct Color(pub [u8; 3]);

impl Color {
    /// `#rrggbb`, for the report.
    #[allow(dead_code)]
    pub fn hex(self) -> String {
        format!("#{:02x}{:02x}{:02x}", self.0[0], self.0[1], self.0[2])
    }
}

#[allow(dead_code)]
mod tokens {
    use super::Color;
    include!(concat!(env!("OUT_DIR"), "/tokens.rs"));
}
pub use tokens::*;

/// The report's CSS variables (`--ground`, `--mint`, `--status-ok`, ...) and its fonts.
pub const REPORT_CSS: &str = include_str!(concat!(env!("OUT_DIR"), "/theme.css"));

/// The fonts, for the window (the latin and latin-ext subsets; anything else falls back to
/// egui's own fonts). Variable fonts: the weight is set when they are loaded.
#[cfg(windows)]
pub mod fonts {
    pub const DISPLAY: [&[u8]; 2] = [include_bytes!("fonts/space-grotesk-latin.ttf"), include_bytes!("fonts/space-grotesk-latin-ext.ttf")];
    pub const TEXT: [&[u8]; 2] = [include_bytes!("fonts/inter-latin.ttf"), include_bytes!("fonts/inter-latin-ext.ttf")];
    pub const MONO: [&[u8]; 2] = [include_bytes!("fonts/jetbrains-mono-latin.ttf"), include_bytes!("fonts/jetbrains-mono-latin-ext.ttf")];
}

/// Status colour and shape ("ok", "warn", anything else = not measured).
#[cfg_attr(not(windows), allow(dead_code))]
pub fn status(key: &str) -> (Color, bool) {
    STATUS.iter().find(|s| s.0 == key).or_else(|| STATUS.iter().find(|s| s.0 == "na")).map(|s| (s.1, s.2)).unwrap_or((DEVICE, false))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tokens_from_core() {
        assert_eq!(GROUND.hex(), "#0a0c0f");
        assert_eq!(status("ok"), (MINT, true));
        assert_eq!(status("warn"), (ORANGE, false));
        assert!(!status("na").1);
        assert!(REPORT_CSS.contains("--mint: #5BE7C4;"));
        assert!(REPORT_CSS.matches("@font-face").count() == 3);
    }
}
